function chooseMob(rng=Math.random){if(rng()<rareChance())return 'treasure';if(s.stage>=3&&rng()<.04){const elites=s.stage>=6?(s.stage>=11?['eliteSlime','eliteMushroom','eliteMoth','eliteSnail','eliteRabbit']:['eliteSlime','eliteMushroom','eliteMoth','eliteSnail']):['eliteSlime','eliteMushroom'];return elites[Math.min(elites.length-1,Math.floor(rng()*elites.length))]}const pool=regionIndex()===0?['slime','mushroom','snail']:regionIndex()===1?['slime','mushroom','moth','snail','rabbit']:['mushroom','moth','snail','rabbit'];return pool[Math.min(pool.length-1,Math.floor(rng()*pool.length))]}
function spawn(){encounterSerial++;if(boss)bossStrikes=0;phase='combat';phaseLeft=0;if(!boss)currentMob=chooseMob();const id=boss?'boss'+bossId:currentMob;s.encounters[id]=(Number(s.encounters[id])||0)+1;maxHp=boss?bossHealth(bossId,bossTier,bossEncounterStage):Math.round(health()*MOBS[currentMob].hp);hp=maxHp;attackClock=0;enemyClock=0;if(currentMob==='treasure'&&!boss){log('희귀 조우! 황금 보물여우가 나타났어요.');notify('✦ 황금 보물여우 등장! 보물을 놓치지 마세요.')}if(!boss&&MOBS[currentMob].elite){log('엘리트 조우 · '+MOBS[currentMob].name);notify('◆ 엘리트 등장! 강한 공격에 대비하세요.')}save();renderCodex()}
function beginTravel(){phase='travel';travelTotal=travelSeconds();phaseLeft=travelTotal;attackClock=0;save()}
function startRecovery(){phase='loot';phaseLeft=.8;hp=0;attackClock=0;save()}
function offline(ms){if(persistence.status==='conflict'||s.rewardPending||s.paused||boss||phase==='defeated'||s.journey?.boss===true||s.journey?.phase==='defeated'||!Number.isFinite(ms)||ms<15000)return;const seconds=Math.min(Math.max(0,ms/1000),28800);const combatSeconds=Math.max(1,Math.ceil(health()/(attack()*(1+crit()))))/speed();const estimatedHit=Math.max(1,Math.max(0,18*Math.pow(1.2,s.stage-1)*1.3-heroDefense())*(1-mitigation()));if(heroMaxHp()/(estimatedHit/2.6)<combatSeconds*1.4){log('현재 지역에서 생존이 어려워 오프라인 골드를 얻지 못했어요.');return}const rate=reward()/(combatSeconds+.8+travelSeconds())*.5;const gain=Math.floor(seconds*rate*goldMultiplier());if(gain>0){s.gold+=gain;log('쉬는 동안 모은 골드 +'+fmt(gain)+' G');notify('다시 오셨네요! 오프라인 보상 +'+fmt(gain)+' G')}}
function upgradeQuote(k,mode=1){if(!Object.hasOwn(upgrades,k)||![1,10,100,'max'].includes(mode))throw Error('올바르지 않은 강화 선택입니다.');const spec=upgrades[k],remaining=spec.max-s[k];let count=0,total=0;const limit=mode==='max'?remaining:Math.min(mode,remaining);for(let i=0;i<limit;i++){const price=upgradePrice(k,s[k]+i);if(mode==='max'&&total+price>s.gold)break;total+=price;count++}return {count,total,target:s[k]+count,canAfford:count>0&&total<=s.gold,capped:remaining<=0,nextCost:cost(k)}}
function upgrade(k,mode=1){if(!canMutate())return {ok:false,reason:'다른 탭의 진행을 새로고침해 주세요.'};const quote=upgradeQuote(k,mode);if(!quote.canAfford)return {ok:false,reason:quote.capped?'최대 레벨입니다.':'골드가 부족합니다.'};s.gold-=quote.total;s[k]=quote.target;log(upgrades[k].name+' +'+quote.count+'회 · '+fmt(quote.total)+' G 사용');save();render();renderLoot();return {ok:true,level:s[k],gold:s.gold,count:quote.count,spent:quote.total}}
function upgradeValue(k,level){if(k==='vitality')return fmt(hpAtLevel(level));if(k==='guard')return fmt(defenseAtLevel(level));if(k==='attack')return fmt(attackAtLevel(level));if(k==='speed')return speedAtLevel(level).toFixed(2)+'/s';if(k==='crit')return pct(Math.min(.75,.05+level*.015+potentialSum('critical')));return moveAtLevel(level).toFixed(2)+'m/s'}
function renderUpgrades(){const signature=JSON.stringify([s.gold,buyMode,...Object.keys(upgrades).map(k=>s[k]),s.slots,s.discovered.length,s.bossWins,s.highestStage,s.passives]);if(signature===upgradeRenderSignature)return;upgradeRenderSignature=signature;for(const k of Object.keys(upgrades)){const q=upgradeQuote(k,buyMode),b=$(k+'-buy');$(k+'-level').textContent='Lv.'+s[k]+' / '+upgrades[k].max;b.disabled=!q.canAfford;b.textContent=q.capped?'최대 레벨':q.count>0?q.count+'회 강화\n◆ '+fmt(q.total)+' G':'골드 부족\n◆ '+fmt(q.nextCost)+' G';b.title=q.capped?'최대 레벨에 도달했습니다.':(q.count||1)+'회 총 비용: '+(q.count?q.total:q.nextCost).toLocaleString('ko-KR')+' 골드';b.setAttribute('aria-label',upgrades[k].name+' '+b.title);$(k+'-effect').textContent=upgradeValue(k,s[k])+(q.count?' → '+upgradeValue(k,q.target):'');} $('forge-gold').textContent='◆ '+fmt(s.gold)+' G';}
function setBuyMode(mode){if(![1,10,100,'max'].includes(mode))return false;buyMode=mode;for(const id of ['1','10','100','max'])$('buy-mode-'+id).setAttribute('aria-pressed',String(String(mode)===id));renderUpgrades();return true}
function damage(amount,critical=false){if(!Number.isFinite(amount)||amount<=0)return;if(phase!=='combat'||s.paused)return;hp-=amount;showImpact(amount,critical);if(hp<=0){const wasBoss=boss;const gearStart=s.nextGearId;const victoryName=wasBoss?BOSSES[bossId].name:MOBS[currentMob].name;const wonSpecial=wasBoss||currentMob==='treasure';const victorySeconds=wasBoss?Math.max(0,BOSS_TIERS[bossTier].time-bossLeft):0;let extraCombatGold=0;const defeatedId=wasBoss?'boss'+bossId:currentMob;if(wasBoss&&bossTier!=='normal'){s.bossVariantWins[bossTier]++;const variantId=defeatedId+'_'+bossTier;s.defeated[variantId]=(Number(s.defeated[variantId])||0)+1;}s.defeated[defeatedId]=(Number(s.defeated[defeatedId])||0)+1;const g=Math.floor((wasBoss?[600,2400,9600,18000,36000][bossId]*(bossTier==='mystic'?12:bossTier==='elite'?3:1):reward()*(MOBS[currentMob]?.elite?4:currentMob==='treasure'?20:1))*goldMultiplier());s.gold+=g;s.total++;if(wasBoss){s.bossWins[bossId]++;log(BOSS_TIERS[bossTier].name+' '+BOSSES[bossId].name+' 격파! +'+fmt(g)+' G');lastLoot=rollLoot(true,bossId);if(s.bossWins[bossId]===1){const firstKey=['ring','scoutboots','mossblade','owlcoat','acornblade'][bossId];const firstGear=award(firstKey);lastLoot.push({key:firstKey,count:1});log('첫 격파 보상! '+ITEMS[firstKey].name+' · '+optionText(firstGear));}boss=true;if(bossGate){s.stage++;s.highestStage=Math.max(s.highestStage,s.stage);s.kills=0;log('다음 스테이지가 열렸어요.')}notify('보스 처치! 전리품을 인벤토리에서 확인하세요.')}else{s.safetyDefeats=0;lastLoot=rollLoot(false);s.kills=Math.min(requiredKills(),s.kills+1);if(s.total%3===1)log(MOBS[currentMob].name+' 처치 · +'+fmt(g)+' G');if(s.kills>=requiredKills()){if(s.farmMode){s.kills=0}else{s.stage++;s.highestStage=Math.max(s.highestStage,s.stage);s.kills=0;log('스테이지 '+s.stage+'에 도착했어요.')}}}progressTrail(wasBoss,defeatedId);progressResearch(wasBoss,defeatedId);if(wonSpecial)captureBattleReward({kind:wasBoss?'boss':'treasure',tier:wasBoss?bossTier:'normal',name:victoryName,gold:g+extraCombatGold,bossId,gearStart,firstClear:wasBoss&&s.bossWins[bossId]===1,seconds:victorySeconds});else startRecovery();renderLoot()}render()}
function startBoss(id=0,rng=Math.random,normalOnly=false){if(!canMutate())return false;if(s.rewardPending||phase==='defeated'||s.heroHp<=0||boss||s.paused||(currentMob==='treasure'&&phase==='combat')||!Number.isInteger(id)||id<0||id>=BOSSES.length||!bossUnlocked(id)||bossRemaining(id)>0)return false;bossId=id;bossGate=false;bossTier=normalOnly===true?'normal':rollBossTier(rng);bossEncounterStage=s.highestStage;boss=true;bossLeft=BOSS_TIERS[bossTier].time;s.bossReadyAt[id]=Date.now()+bossCooldown(id,bossTier)*1000;spawn();$('boss-dialog').close();$('quick-boss-dialog').close();showView('battle');log(BOSS_TIERS[bossTier].name+' '+BOSSES[id].name+' 등장 · 제한 '+bossLeft+'초');notify(BOSS_TIERS[bossTier].name+' 보스 등장!');render();return true}
function render(){if(tickRendering)return;renderFieldNotes();renderResearch();renderFarmMode();renderQuickBoss();renderBossDock();renderExpedition();renderPassives();const region=Math.min(3,Math.floor((s.stage-1)/5));$('gold').textContent=fmt(s.gold);$('stage').textContent='STAGE '+s.stage+'–'+Math.min(requiredKills(),s.kills+1);$('zone').textContent=names[region];$('enemy-name').textContent=boss?BOSS_TIERS[bossTier].name+' '+BOSSES[bossId].name+' · BOSS':MOBS[currentMob].name+(MOBS[currentMob].elite?' · ELITE':'');$('enemy-hp-label').textContent=fmt(Math.max(0,hp))+' / '+fmt(maxHp);$('enemy-hp').style.width=Math.max(0,hp/maxHp*100)+'%';$('progress-label').textContent=s.kills+' / '+requiredKills();$('progress-bar').style.width=s.kills/requiredKills()*100+'%';$('reward-label').textContent=boss?'남은 시간 '+Math.ceil(bossLeft)+'초':'처치 보상 +'+fmt(Math.floor(reward()*(MOBS[currentMob]?.elite?4:currentMob==='treasure'?20:1)*goldMultiplier()))+' G';$('battle-status').textContent=s.paused?'Ⅱ 모험 쉬는 중':boss?'● 보스 전투 중':'● 자동 사냥 중';$('pause').textContent=s.paused?'▶ 사냥 재개':'Ⅱ 일시 정지';$('arena').classList.toggle('boss-arena',boss);$('boss').disabled=phase==='defeated'||boss||s.paused||(currentMob==='treasure'&&phase==='combat');$('boss').textContent=boss?'♜ 전투 중':'♜ 보스 원정';$('battle-hint').textContent=boss?BOSS_TIERS[bossTier].time+'초 안에 처치하세요. 패시브가 자동 발동합니다.':!bossUnlocked(0)?'첫 보스 해금까지 몬스터 '+(10-s.total)+'마리 · 보스 원정에서 보상을 확인하세요.':'스테이지는 자동 진행됩니다. 보스 원정에서 재도전 시간을 확인하세요.';$('atk').textContent=fmt(attack());$('speed').textContent=speed().toFixed(2)+'/s';$('crit').textContent=Math.round(crit()*100)+'%';$('hero-level').textContent='Lv. '+(1+Math.floor(s.total/10));$('title-text').textContent=s.stage<6?'작은 모험의 시작':'숲이 기억하는 모험가';renderUpgrades();renderHero();renderHeroStats();renderTravel();renderEncounter();renderBossPattern();$('boss-timer').hidden=!boss||phase!=='combat';$('boss-seconds').textContent=Math.max(0,bossLeft).toFixed(1);$('boss-time-fill').style.width=Math.max(0,bossLeft/BOSS_TIERS[bossTier].time*100)+'%';$('boss-timer').classList.toggle('urgent',bossLeft<=10);$('chapter-label').textContent=(region+1)+' / 4';for(let i=0;i<4;i++){const el=$('journey-'+i);el.classList.toggle('active',i===region);el.querySelector('b').textContent=i===region?'탐험 중':i<region?'완료':'잠김'}}
$('pause').onclick=()=>{s.paused=!s.paused;save();render()};$('boss').onclick=openQuickBoss;for(const k of Object.keys(upgrades))$(k+'-buy').onclick=()=>upgrade(k,buyMode);$('help').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=()=>$('help-dialog').close();
