function rollLoot(isBoss,id=0,rng=Math.random){const drops=[];for(const [dropKey,p] of isBoss?BOSS_TABLES[id]:MOBS[currentMob].drops){const natural=rng()<itemDropChance(dropKey,p,isBoss,bossTier),eligible=isBoss&&!!ITEMS[dropKey].blueprint&&!known(dropKey),guaranteed=eligible&&(s.blueprintMisses[dropKey]||0)>=59;if(eligible){if(natural||guaranteed)s.blueprintMisses[dropKey]=0;else s.blueprintMisses[dropKey]=(s.blueprintMisses[dropKey]||0)+1}if(natural||guaranteed){if(guaranteed&&!natural)log('보스 연구 완성 · '+ITEMS[dropKey].name+' 확정 발견');const duplicate=ITEMS[dropKey].blueprint&&known(dropKey),key=duplicate?'dust':dropKey;const count=duplicate?3:isBoss&&key==='core'?id+1:1;if(duplicate)log(ITEMS[dropKey].name+' 중복 · 별빛 가루 3개로 전환');const gear=award(key,count,rng,isBoss?BOSSES[id].name:MOBS[currentMob].name);drops.push({key,count});if(gear)log(ITEMS[key].name+' · '+optionText(gear));log('획득! '+ITEMS[key].name+' ×'+count);if(['epic','legendary','mythic'].includes(ITEMS[key].rarity)){notify('✦ '+RARITIES[ITEMS[key].rarity]+' 발견! '+ITEMS[key].name);$('loot-announcement').textContent='최근 희귀 획득 · '+ITEMS[key].name;}}}if(isBoss&&bossTier!=='normal'){const pool=bossTier==='mystic'?(id===2?['royalblade']:['crown']):[['guardiancoat'],['guardianlegs'],['sunblade'],['windboots'],['guardiancoat','guardianlegs']][id];const key=pool[Math.min(pool.length-1,Math.floor(rng()*pool.length))];award(key,1,rng);drops.push({key,count:1});const stones=bossTier==='mystic'?10:3;award('skillstone',stones);drops.push({key:'skillstone',count:stones});log(BOSS_TIERS[bossTier].name+' 확정 보너스 · '+ITEMS[key].name+' / 스킬석 '+stones+'개')}return drops}
