function canCraft(key){return Object.hasOwn(RECIPES,key)&&(!ITEMS['bp_'+key]||known('bp_'+key))&&s.gold>=CRAFT_GOLD[key]&&Object.entries(RECIPES[key]).every(([k,v])=>(s.inventory[k]||0)>=v)}
function craft(key){if(!canMutate())return false;hideCraftTip();const recipe=RECIPES[key];if(!canCraft(key))return false;s.gold-=CRAFT_GOLD[key];for(const [k,v] of Object.entries(recipe))s.inventory[k]-=v;const gear=award(key,1,Math.random,'장비 제작');selectedItem=key;selectedGearId=gear?.id||null;log(ITEMS[key].name+' 제작 · '+optionText(gear));notify('제작 완료! '+CRAFT_GOLD[key]+' G를 사용했어요.');save();render();renderLoot();return true}
function hideGearTip(){clearTimeout(gearTipTimer);gearPopoverId=null;$('gear-tooltip').hidden=true}
function showGearTip(g,anchor){clearTimeout(gearTipTimer);if(!g)return;gearPopoverId=g.id;const item=ITEMS[g.key],tip=$('gear-tooltip');tip.setAttribute('data-rarity',item.rarity);$('tip-name').textContent=item.name;$('tip-rarity').textContent=RARITIES[item.rarity]+' · '+SLOT_NAMES[item.slot]+(g.exceptional?' · 대성공':'');$('tip-stats').textContent=gearText(g);$('tip-option').textContent=optionText(g);$('tip-rare').hidden=!g.ward;$('tip-rare').textContent=g.ward?'◆ 숲의 가호 · 피해감소 +'+pct(g.ward):'';const equipped=equippedGear(item.slot);$('tip-comparison').textContent=equipped?(equipped.id===g.id?'현재 장착 중':'현재 장비: '+gearText(equipped)+(equipped.ward?' · 숲의 가호 +'+pct(equipped.ward):'')):'이 슬롯에 장착한 장비가 없습니다.';potentialRows($('tip-potentials'),g.potentials);positionItemTip(tip,anchor,330)}
function gearButton(g,slotView=false){const item=ITEMS[g.key],b=document.createElement('button');b.className='gear-tile '+item.rarity+(s.slots[item.slot]===g.id?' equipped':'')+(g.exceptional?' exceptional':'')+(g.ward?' warded':'');b.setAttribute('aria-describedby','gear-tooltip');b.setAttribute('aria-label',item.name+' 옵션 확인');const icon=document.createElement('span');icon.className='gear-icon';paintItemIcon(icon,item);const name=document.createElement('strong');name.textContent=item.name;const tag=document.createElement('small');tag.textContent=(slotView?SLOT_NAMES[item.slot]:RARITIES[item.rarity])+(s.slots[item.slot]===g.id?' · 장착':'')+(g.quantity>1?' ×'+g.quantity:'')+(g.exceptional?' ✦':'')+(g.ward?' ◆ 가호':'');b.append(icon,name,tag);b.onmouseenter=()=>showGearTip(g,b);b.onmouseleave=hideGearTip;b.onfocus=()=>showGearTip(g,b);b.onblur=()=>hideGearTip();b.onclick=()=>{selectedGearId=g.id;openPotential(g.id)};return b}
function renderEquipment(){
 for(const key of ['all',...Object.keys(SLOT_NAMES)]){$('gear-category-'+key).setAttribute('aria-pressed',String(gearFilter===key));$('gear-count-'+key).textContent=s.gear.filter(g=>key==='all'||ITEMS[g.key].slot===key).reduce((n,g)=>n+g.quantity,0)}$('gear-list-title').textContent=gearFilter==='all'?'전체 장비':SLOT_NAMES[gearFilter];const signature=JSON.stringify([s.gear,s.slots,gearFilter,gearSort]);$('gear-effects').textContent='HP '+fmt(heroMaxHp())+' · 방어 '+fmt(heroDefense())+' · 공격력 '+fmt(attack())+' · 이동 '+movementSpeed().toFixed(2)+'m/s · 드롭 ×'+luck().toFixed(2);if(signature===equipmentSignature)return;equipmentSignature=signature;hideGearTip();const slots=$('equipment-slots');slots.replaceChildren();for(const slot of Object.keys(SLOT_NAMES)){const g=equippedGear(slot);if(g)slots.append(gearButton(g,true));else{const empty=document.createElement('div');empty.className='empty-gear-slot';const title=document.createElement('strong');title.textContent=SLOT_NAMES[slot];const hint=document.createElement('small');hint.textContent='미장착';empty.append(title,hint);slots.append(empty)}}
 $('gear-effects').textContent='HP '+fmt(heroMaxHp())+' · 방어 '+fmt(heroDefense())+' · 공격력 '+fmt(attack())+' · 이동 '+movementSpeed().toFixed(2)+'m/s · 드롭 ×'+luck().toFixed(2);
 const list=$('gear-list');list.replaceChildren();const gears=s.gear.filter(g=>gearFilter==='all'||ITEMS[g.key].slot===gearFilter).slice().sort((a,b)=>gearSort==='rarity'?rarityRank(ITEMS[b.key].rarity)-rarityRank(ITEMS[a.key].rarity)||gearScore(b)-gearScore(a):Number(b.id.slice(1))-Number(a.id.slice(1)));$('gear-visible-count').textContent=gears.reduce((n,g)=>n+g.quantity,0)+'개 보유';if(!gears.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='보유 장비가 없습니다. 사냥이나 제작으로 모아 보세요.';list.append(empty)}for(const g of gears){const row=document.createElement('div');row.className='gear-cell '+ITEMS[g.key].rarity;row.append(gearButton(g));const action=document.createElement('button');action.className='gear-action';action.textContent=s.slots[ITEMS[g.key].slot]===g.id?'해제':'장착';action.onclick=()=>equipGear(g.id);const actions=document.createElement('div');actions.className='gear-actions';const lock=document.createElement('button');lock.className='gear-lock';lock.textContent=g.locked?'잠금 해제':'잠금';lock.setAttribute('aria-pressed',String(g.locked));lock.setAttribute('aria-label',ITEMS[g.key].name+' '+(g.locked?'잠금 해제':'잠금'));lock.onclick=()=>toggleGearLock(g.id);const salvage=document.createElement('button');salvage.className='gear-salvage';salvage.textContent='분해';salvage.disabled=g.locked||s.slots[ITEMS[g.key].slot]===g.id;salvage.setAttribute('aria-label',ITEMS[g.key].name+' 분해 보상 확인');salvage.onclick=()=>previewDismantle(g.id);actions.append(action,salvage,lock);row.append(actions);list.append(row)}
}
let craftTipKey=null,craftTipTimer=null;
function hideCraftTip(){clearTimeout(craftTipTimer);craftTipKey=null;$('craft-tooltip').hidden=true}
function showCraftTip(key,anchor){if(!Object.hasOwn(RECIPES,key))return;clearTimeout(craftTipTimer);craftTipKey=key;$('craft-tip-name').textContent=known(key)?ITEMS[key].name:CRAFT_LABELS[key]+' 설계도';const list=$('craft-tip-materials');list.replaceChildren();for(const [k,n] of Object.entries(RECIPES[key])){const row=document.createElement('p');row.textContent=ITEMS[k].name+' · '+(s.inventory[k]||0)+' / '+n;row.className=(s.inventory[k]||0)>=n?'enough':'missing';list.append(row)}$('craft-tip-gold').textContent='골드 '+fmt(s.gold)+' / '+CRAFT_GOLD[key]+' G';$('craft-tip-gold').className=s.gold>=CRAFT_GOLD[key]?'enough':'missing';$('craft-tip-status').textContent=canCraft(key)?'제작 가능 · 재료와 골드를 소모합니다.':(ITEMS['bp_'+key]&&!known('bp_'+key)?ITEMS['bp_'+key].desc:'재료와 골드를 모두 준비해 주세요.');positionItemTip($('craft-tooltip'),anchor,290)}
function renderHeroStats(){const fields={'stat-hp':fmt(Math.max(0,s.heroHp))+' / '+fmt(heroMaxHp()),'stat-defense':fmt(heroDefense()),'stat-reduction':Math.round(mitigation()*100)+'%','stat-move':movementSpeed().toFixed(2)+'m/s','stat-drop':'×'+luck().toFixed(3),'stat-gold':'×'+goldMultiplier().toFixed(3),'stat-crit-damage':'×2.00','stat-expedition':pct(expeditionReduction()),'stat-dodge':pct(dodgeChance()),'stat-boss-reduction':pct(bossMitigation()),'stat-regen':pct(Math.min(.01,potentialSum('regen')))+'/초','stat-leech':pct(Math.min(.06,potentialSum('leech'))+.02*passivePower('leech')),'stat-chain':pct(Math.min(.1,potentialSum('chain')))};for(const [id,value] of Object.entries(fields))$(id).textContent=value;}
function renderHero(){s.heroHp=Math.min(s.heroHp,heroMaxHp());$('hero-hp-label').textContent=fmt(Math.max(0,s.heroHp))+' / '+fmt(heroMaxHp());$('hero-hp-fill').style.width=Math.max(0,s.heroHp/heroMaxHp()*100)+'%';$('hero-hp-box').classList.toggle('critical',s.heroHp/heroMaxHp()<.3);$('hero-danger').textContent=s.heroHp/heroMaxHp()<.3?'위험 · HP와 방어 장비를 강화하세요':'적 공격까지 '+Math.max(0,enemyInterval()-enemyClock).toFixed(1)+'초';$('hero-danger').hidden=phase!=='combat';$('hero-defense').textContent='방어 '+heroDefense()+' · 피해 감소 '+Math.round(mitigation()*100)+'%';$('enemy-attack-info').textContent=phase==='combat'?'적 공격 '+enemyAttack()+' · '+enemyInterval().toFixed(1)+'초마다 / 다음 공격 '+Math.max(0,enemyInterval()-enemyClock).toFixed(1)+'초':'비전투 중';}
function renderLoot(){
 refreshPotentialDialog();
 $('luck-value').textContent='드롭 확률 ×'+luck().toFixed(2);$('equipped-label').textContent='장비의 개별 옵션은 위 장비창에서 비교하고 장착하세요.';
 $('inventory-count').textContent=Object.keys(ITEMS).filter(k=>s.inventory[k]>0).length+'종 보유';
 const visibleKeys=Object.keys(ITEMS).filter(k=>s.inventory[k]>0&&(inventoryFilter!=='gear'||ITEMS[k].slot)&&(inventoryFilter!=='materials'||(!ITEMS[k].slot&&!ITEMS[k].blueprint))&&(inventoryFilter!=='blueprints'||ITEMS[k].blueprint));if(!visibleKeys.includes(selectedItem))selectedItem=visibleKeys[0]||null;
 const grid=$('inventory-grid');grid.replaceChildren();
 for(const [key,item] of Object.entries(ITEMS).sort((a,b)=>bagSort==='rarity'?rarityRank(b[1].rarity)-rarityRank(a[1].rarity):0)){if(!(s.inventory[key]>0))continue;if(inventoryFilter==='materials'&&(item.slot||item.blueprint))continue;if(inventoryFilter==='blueprints'&&!item.blueprint)continue;if(inventoryFilter==='gear'&&!item.slot)continue;const b=document.createElement('button');b.className='item-slot '+(known(key)?item.rarity:'unknown')+(selectedItem===key?' selected':'')+(!s.inventory[key]?' unowned':'');b.setAttribute('aria-label',itemName(key)+' '+(s.inventory[key]||0)+'개');b.setAttribute('aria-pressed',String(selectedItem===key));const icon=document.createElement('span');icon.className='item-symbol';if(known(key))paintItemIcon(icon,item);else icon.textContent='?';const name=document.createElement('strong');name.textContent=itemName(key);const count=document.createElement('small');count.textContent=(Object.keys(SLOT_NAMES).some(slot=>equippedGear(slot)?.key===key)?'장착 · ':'')+'×'+fmt(s.inventory[key]||0);b.append(icon,name,count);b.onclick=()=>{selectedItem=key;renderLoot()};grid.append(b)}
 if(!grid.children.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='아직 획득한 아이템이 없어요. 사냥을 계속해 보세요.';grid.append(empty)}
 const item=ITEMS[selectedItem];$('item-title').textContent=item?item.name+' · '+RARITIES[item.rarity]:'선택한 아이템이 없습니다';$('item-description').textContent=item?item.desc:'사냥으로 얻은 아이템이 이곳에 표시됩니다.';$('equip-item').hidden=!item?.slot;$('equip-item').disabled=!item?.slot;$('equip-item').textContent='최고 옵션 장비 장착 / 해제';
 for(const key of Object.keys(RECIPES)){$('craft-'+key).disabled=!canCraft(key);$('craft-'+key).textContent=ITEMS['bp_'+key]&&!known('bp_'+key)?'설계도 미획득':'제작 · '+CRAFT_GOLD[key]+' G';$('recipe-card-'+key).className='recipe-card '+ITEMS[key].rarity;$('recipe-'+key).textContent=known(key)?ITEMS[key].name:CRAFT_LABELS[key]+' 설계도';}
 if(craftTipKey&&!$('craft-tooltip').hidden)showCraftTip(craftTipKey,$('recipe-info-'+craftTipKey));
 renderBossList();
 renderCodex();renderEquipment();renderCollection();renderFieldNotes();
}
