function bossEntryReason(id){if(s.rewardPending)return '전리품 확인을 마쳐 주세요.';if(boss)return '보스와 전투 중입니다.';if(s.paused)return '사냥을 재개하면 입장할 수 있습니다.';if(phase==='defeated'||s.heroHp<=0)return '모험가가 회복 중입니다.';if(currentMob==='treasure'&&phase==='combat')return '보물여우 전투를 먼저 마쳐 주세요.';if(!bossUnlocked(id))return BOSSES[id].desc;const wait=bossRemaining(id);return wait?'재도전까지 '+formatBossTime(wait):''}
function openQuickBoss(){quickBossId=null;quickBossSignature='';renderQuickBoss(true);$('quick-boss-dialog').showModal();return true}
function selectQuickBoss(id){if(!Number.isInteger(id)||id<0||id>=BOSSES.length)return false;quickBossId=id;quickBossSignature='';renderQuickBoss(true);return true}
function renderQuickBoss(force=false){if(!force&&!$('quick-boss-dialog').open)return;const signature=JSON.stringify([quickBossId,s.total,s.highestStage,s.heroHp>0,s.paused,boss,s.rewardPending,phase,s.expedition,currentMob,s.bossReadyAt.map((_,i)=>bossRemaining(i)),s.blueprintMisses,s.discovered,luck(),expeditionReduction(),attack(),speed(),crit()]);if(signature===quickBossSignature)return;quickBossSignature=signature;const list=$('quick-boss-list');if(force||!list.children.length){list.replaceChildren();BOSSES.forEach((b,id)=>{const btn=document.createElement('button');btn.className='quick-boss-row';btn.setAttribute('aria-pressed',String(quickBossId===id));const icon=document.createElement('img');icon.src=bossSprite(id);icon.alt='';const title=document.createElement('strong');title.textContent=b.name;const status=document.createElement('small');status.id='quick-boss-status-'+id;btn.append(icon,title,status);btn.onclick=()=>selectQuickBoss(id);list.append(btn)})}BOSSES.forEach((b,id)=>{const status=list.children[id].children[2];status.textContent=!bossUnlocked(id)?b.desc:bossRemaining(id)?'대기 '+formatBossTime(bossRemaining(id)):'도전 가능';list.children[id].setAttribute('aria-pressed',String(quickBossId===id))});const id=quickBossId;$('quick-boss-detail').hidden=id===null;$('quick-boss-prompt').hidden=id!==null;if(id===null)return;const b=BOSSES[id],ch=bossTierChances();const defenseFactor=(1-mitigation())*(1-bossMitigation()),hit=Math.max(1,Math.round((bossBaseAttack(id)-heroDefense())*defenseFactor)),heavy=Math.max(1,Math.round((bossBaseAttack(id)*BOSS_BALANCE[id].power-heroDefense())*defenseFactor));$('quick-boss-survival').textContent='현재 방어 기준 · 일반 공격 약 '+fmt(hit)+' / 강타 약 '+fmt(heavy)+' 피해 · 회피·방벽·격앙 제외';const rec=s.fieldNotes.bosses[id+'_normal'];$('quick-boss-history').textContent=rec?'업데이트 후 일반 격파 '+rec.wins+'회 · 최고 기록 '+(Number.isFinite(rec.best)?rec.best.toFixed(1)+'초':'시간 기록 없음'):'새 기록에 도전하세요 · 일반/엘리트/미스틱 기록은 따로 저장됩니다.';$('quick-boss-name').textContent=b.name;$('quick-boss-story').textContent=['작은 왕관을 지키는 숲 입구의 거북. 첫 보스 장비를 노려보세요.','오래된 돌길에서 잠든 수호자. 첫 보스보다 충분한 공격력과 방어력이 필요합니다.','깊은 숲길을 지키는 대장. 장비와 잠재를 갖춘 뒤 도전하는 장기 목표입니다.','달빛 가지의 졸린 부엉이. 달깃과 월영 설계도를 지킵니다.','숲 가장자리 도토리 기사. 호박철과 도토리 설계도를 지킵니다.'][id];$('quick-boss-stats').textContent='일반 HP '+fmt(bossHealth(id))+' · 공격 '+bossBaseAttack(id)+' · 제한 60초 · '+bossPatternText(id);$('quick-boss-estimate').textContent='현재 기본 공격 기준 예상 '+Math.ceil(bossHealth(id)/(attack()*speed()*(1+crit())))+'초 · 패시브/생존/변이 미반영';$('quick-boss-blueprint').textContent=blueprintProgressText(id);$('quick-boss-rewards').textContent='첫 격파: '+ITEMS[['ring','scoutboots','mossblade','owlcoat','acornblade'][id]].name+' · 전용 재료 확정 · 전용 설계도 '+pct(itemDropChance('bp_'+['shellcoat','runelegs','groveblade','moonboots','acorncoat'][id],BOSS_TABLES[id].find(x=>ITEMS[x[0]].blueprint)[1],true))+' (일반, 현재 드롭률)';$('quick-boss-variants').textContent='엘리트 '+pct(ch.elite)+' / 미스틱 '+pct(ch.mystic)+' · 변이 탐색에서만 추첨 / 일반 원정은 일반 확정';$('quick-boss-wait').textContent='일반 원정 대기 '+formatBossTime(bossCooldown(id))+' · 입장 시 시작';const reason=bossEntryReason(id);$('quick-boss-reason').textContent=reason||'준비되었습니다. 입장하면 보스 전투가 시작됩니다.';$('quick-boss-enter').disabled=!!reason;$('quick-boss-normal').disabled=!!reason;}
function renderFarmMode(){$('farm-mode').setAttribute('aria-pressed',String(s.farmMode));$('farm-mode').textContent=s.farmMode?'현재 지역 반복 사냥':'자동 스테이지 돌파';$('farm-mode-note').textContent=s.farmMode?'처치 목표를 채워도 현재 지역에서 재료를 모읍니다.':'처치 목표를 채우면 다음 스테이지로 이동합니다.'}
